CREATE OR REPLACE FUNCTION public.validate_news_options() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF cardinality(NEW.poll_options)=1 OR cardinality(NEW.poll_options)>8 THEN RAISE EXCEPTION 'Choose 2 to 8 poll options'; END IF; IF EXISTS(SELECT 1 FROM unnest(NEW.poll_options) v WHERE length(trim(v))=0 OR length(v)>200) THEN RAISE EXCEPTION 'Poll options must contain 1 to 200 characters'; END IF; IF NEW.kind<>'system' AND (NEW.popup OR NEW.question_enabled OR cardinality(NEW.poll_options)>0) THEN RAISE EXCEPTION 'Interactive content is only available for news'; END IF; RETURN NEW; END $$; CREATE TRIGGER validate_news_options BEFORE INSERT OR UPDATE ON public.mail FOR EACH ROW EXECUTE FUNCTION public.validate_news_options();